1	import { describe, it, expect } from "vitest";
2	import { runScenario } from "./claim-office.js";
3	
4	describe("MHPCO Claim Office", () => {
5	  // --- Base premiums for main items ---
6	  it("quotes an empty item list at 5 G (processing fee only)", () => {
7	    const result = runScenario({
8	      customer: { yearsWithMHPCO: 0 },
9	      steps: [{ op: "quote", items: [] }],
10	    });
11	
12	    expect(result).toEqual({ results: [{ premium: 5 }] });
13	  });
14	  it("quotes a plain sword at 105 G (100 G base + 5 G fee)", () => {
15	    const result = runScenario({
16	      customer: { yearsWithMHPCO: 0 },
17	      steps: [{ op: "quote", items: [{ type: "sword" }] }],
18	    });
19	
20	    expect(result).toEqual({ results: [{ premium: 105 }] });
21	  });
22	  it("quotes a plain amulet at 65 G (60 G base + 5 G fee)", () => {
23	    const result = runScenario({
24	      customer: { yearsWithMHPCO: 0 },
25	      steps: [{ op: "quote", items: [{ type: "amulet" }] }],
26	    });
27	
28	    expect(result).toEqual({ results: [{ premium: 65 }] });
29	  });
30	  it("quotes a plain staff at 85 G (80 G base + 5 G fee)", () => {
31	    const result = runScenario({
32	      customer: { yearsWithMHPCO: 0 },
33	      steps: [{ op: "quote", items: [{ type: "staff" }] }],
34	    });
35	
36	    expect(result).toEqual({ results: [{ premium: 85 }] });
37	  });
38	  it("quotes a plain potion at 45 G (40 G base + 5 G fee)", () => {
39	    const result = runScenario({
40	      customer: { yearsWithMHPCO: 0 },
41	      steps: [{ op: "quote", items: [{ type: "potion" }] }],
42	    });
43	
44	    expect(result).toEqual({ results: [{ premium: 45 }] });
45	  });
46	
47	  // --- Components and the building block of 3 alike components ---
48	  it.todo("quotes a single rune at 25 G base premium");
49	  it.todo("quotes 2 runes at 50 G base premium");
50	  it.todo("quotes 3 runes at 60 G base premium (block applies)");
51	  it.todo("quotes 4 runes at 100 G base premium (no block — block requires exactly 3)");
52	  it.todo("quotes 7 runes at 175 G base premium (no block — block requires exactly 3)");
53	  it.todo("quotes 2 runes + 1 moonstone at 75 G base premium (no block: different types)");
54	  it.todo("quotes 3 runes + 3 moonstones at 120 G base premium (two separate blocks)");
55	
56	  // --- Item-specific premium modifiers ---
57	  it.todo("adds a 50 % curse surcharge to the cursed item's base premium");
58	  it.todo("adds a 30 % surcharge for enchantment exactly 5");
59	  it.todo("adds no high-enchantment surcharge for enchantment 4");
60	  it.todo("applies both curse and high-enchantment surcharges to a cursed sword with enchantment 5");
61	  it.todo(
62	    "applies the curse surcharge only to the cursed item on a multi-item policy — cursed sword + plain amulet → 210 G before further modifiers and fee",
63	  );
64	
65	  // --- Policy-wide premium modifiers ---
66	  it.todo("applies a 20 % loyalty discount for a customer with exactly 2 years with MHPCO");
67	  it.todo("applies no loyalty discount for a customer with 1 year with MHPCO");
68	  it.todo("applies a 10 % first insurance surcharge to every quote");
69	  it.todo("applies a 15 % follow-up discount to the customer's second quote");
70	
71	  // --- Rounding ---
72	  it.todo("rounds a premium of 197.5 G up to 198 G (in the MHPCO's favour)");
73	  it.todo("rounds a payout of 350.5 G down to 350 G (in the MHPCO's favour)");
74	
75	  // --- Integration examples for the premium ---
76	  it.todo("quotes a newcomer's cursed steel sword (enchantment 3) at 165 G");
77	  it.todo("quotes a 3-year customer's second contract for a cursed sword (enchantment 7) at 160 G");
78	
79	  // --- Claim processing: standard reimbursement ---
80	  it.todo("pays out 400 G for a regular steel sword (enchantment 3) with 500 G damage (full minus 100 G deductible)");
81	  it.todo("pays out 100 G for a damaged rune with 200 G damage (no enchantment or material, so no special clause)");
82	
