86	  it.todo("pays out 400 G for a dragon-material sword with enchantment 8 and 1000 G damage (50 % clause wins, then deductible)");
87	  it.todo("pays out 400 G for a dragon-material sword with enchantment 9 and 1000 G damage (50 % clause wins, then deductible)");
88	
89	  // --- Deductible per damage event ---
