95	  it.todo("caps a cursed sword policy at 2000 G — premium modifiers do not raise the cap");
96	  it.todo("caps a policy of a sword and 3 runes at 3500 G (insurance sum 1750 G — the block discount affects the premium only)");
97	  it.todo("exhausts the cap over successive claims — two 1500 G claims on a sword policy → payout 1400 G (cap 600 G left), then 600 G (cap 0 G left)");
98	
99	  // --- Multiple items of the same type ---
100	  it.todo("insures two swords at an insurance sum of 2000 G (cap 4000 G)");
101	  it.todo("treats two sword damage entries as separate damages, each with its own deductible");
102	
103	  // --- Errors ---
104	  it.todo("rejects a quote containing an item with an unknown type");
105	  it.todo("rejects a claim whose damage entry references an item not covered by the policy");
106	  it.todo("rejects a claim whose damage entry has an unknown item type");
107	  it.todo("rejects a claim with more damage entries of a type than the policy covers");
108	  it.todo("rejects a claim containing a damage entry with a negative amount");
109	});
